import sys

def count_substrings(n, k, strings):
    from collections import defaultdict

    def count_occurrences(s, substr):
        count = start = 0
        while True:
            start = s.find(substr, start) + 1
            if start > 0:
                count += 1
            else:
                break
        return count

    results = []
    for i in range(n):
        string = strings[i]
        substring_count = defaultdict(int)
        for j in range(n):
            for l in range(len(string)):
                for r in range(l, len(string)):
                    substring = string[l:r+1]
                    if substring in strings[j]:
                        substring_count[substring] += 1
        valid_pairs = 0
        for substring, count in substring_count.items():
            if count >= k:
                valid_pairs += 1
        results.append(valid_pairs)
    return results

